"""Cut pull request diffs down to what is worth showing Claude."""

from __future__ import annotations

import re
from collections.abc import Iterable
from typing import Any

# Files regenerated by tooling. They inflate a diff without saying anything about
# the change, and they conflict on every pull request that touches them.
GENERATED_NAMES = frozenset({
    "bun.lock",
    "package-lock.json",
    "pnpm-lock.yaml",
    "pyi_hashes.json",
    "uv.lock",
    "yarn.lock",
})

_FILE_HEADER = re.compile(r"^diff --git a/(?:.*) b/(.*)$", re.MULTILINE)


def is_generated(path: str) -> bool:
    """Tell whether a file is regenerated by tooling rather than written by hand.

    Args:
        path: The repository-relative path.

    Returns:
        Whether the file is a lockfile, a stub, or a stub hash list.
    """
    return path.rsplit("/", 1)[-1] in GENERATED_NAMES or path.endswith(".pyi")


def split(diff: str) -> list[tuple[str, str]]:
    """Split a unified diff into one section per file.

    Args:
        diff: The diff as ``git diff`` prints it.

    Returns:
        Each file's path (its new name) and its section of the diff.
    """
    headers = list(_FILE_HEADER.finditer(diff))
    return [
        (match.group(1), diff[match.start() : end])
        for match, end in zip(
            headers,
            [next_match.start() for next_match in headers[1:]] + [len(diff)],
            strict=True,
        )
    ]


def budget(diff: str, limit: int) -> tuple[str, list[str]]:
    """Keep whole file sections of a diff until a size budget runs out.

    Generated files are dropped first; sections are kept in diff order, so the
    result never ends mid-file.

    Args:
        diff: The full diff.
        limit: The most characters to keep.

    Returns:
        The kept sections, and the paths left out (generated or over budget).
    """
    kept: list[str] = []
    left_out: list[str] = []
    used = 0
    for path, section in split(diff):
        if is_generated(path) or used + len(section) > limit:
            left_out.append(path)
            continue
        kept.append(section)
        used += len(section)
    return "".join(kept), left_out


def file_list(files: Iterable[dict[str, Any]], limit: int = 300) -> str:
    """Describe changed files one per line.

    Args:
        files: Entries of the pulls files API.
        limit: The most files to list.

    Returns:
        The list, ending with a count of the files it leaves out.
    """
    entries = list(files)
    lines = [
        f"- {entry['filename']} ({entry['status']}, "
        f"+{entry['additions']} -{entry['deletions']})"
        for entry in entries[:limit]
    ]
    if len(entries) > limit:
        lines.append(f"- ...and {len(entries) - limit} more files")
    return "\n".join(lines)
